import { getTestFlakiness, } from "@allurereport/core-api";
export const createFlakyDetector = ({ includePassedTests = false, historyDepth, stabilizationPeriod } = {}) => (tr, history) => {
    if (tr.status !== "failed" && tr.status !== "broken" && !(includePassedTests && tr.status === "passed")) {
        return false;
    }
    return getTestFlakiness(tr, history, { historyDepth, stabilizationPeriod }) === true;
};
